<?php require_once __DIR__.'/../includes/header.php';checkAuth(['economia','admin']);$db=getDBConnection();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$db->prepare('INSERT INTO insumos(nombre,unidad_medida,stock_actual,stock_minimo,precio_compra_unidad,codigo,updated_at) VALUES(?,?,?,?,?,?,?)');$s->execute([trim($_POST['nombre']),trim($_POST['unidad']),max(0,(float)$_POST['stock']),max(0,(float)$_POST['minimo']),(float)$_POST['precio'],trim($_POST['codigo']),now()]);$msg='Insumo creado.';}$rows=$db->query('SELECT * FROM insumos WHERE activo=1 ORDER BY nombre')->fetchAll();?><div class="card"><h1>Almacén</h1><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif;?><form method="post" class="form-grid"><div><label>Producto</label><input name="nombre" placeholder="Carne de cerdo" required></div><div><label>Unidad</label><input name="unidad" placeholder="libra, pomo, quintal..." required></div><div><label>Stock inicial</label><input type="number" step="0.01" name="stock" required></div><div><label>Stock mínimo</label><input type="number" step="0.01" name="minimo" value="0"></div><div><label>Precio de compra por unidad</label><input type="number" step="0.01" name="precio" required></div><div><label>Código</label><input name="codigo"></div><div class="full"><button class="btn gold">Crear insumo</button></div></form></div><div class="card"><div class="table-wrap"><table><tr><th>Producto</th><th>Unidad</th><th>Stock</th><th>Mínimo</th><th>Costo/U</th><th>Valor</th><th>Estado</th></tr><?php foreach($rows as $r):$low=$r['stock_actual']<=$r['stock_minimo'];?><tr><td><b><?=h($r['nombre'])?></b><br><span class="muted"><?=h($r['codigo'])?></span></td><td><?=h($r['unidad_medida'])?></td><td><?=number_format($r['stock_actual'],2,',','.')?></td><td><?=number_format($r['stock_minimo'],2,',','.')?></td><td><?=money($r['precio_compra_unidad'])?></td><td class="gold"><?=money($r['stock_actual']*$r['precio_compra_unidad'])?></td><td><?=$low?'<span class="badge">Reponer</span>':'<span class="badge">Normal</span>'?></td></tr><?php endforeach;?></table></div></div><?php require_once __DIR__.'/../includes/footer.php';?>
